function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof YASHOVARMAN_INFO&&(e.innerHTML=YASHOVARMAN_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderScholars(){const e=document.getElementById("scholars-grid");e&&"undefined"!=typeof COURT_LITERATURE&&(e.innerHTML=COURT_LITERATURE.map(e=>`\n        <div class="scholar-card">\n            <h3>📜 ${e.scholar}</h3>\n            <span class="role-tag">${e.role}</span>\n            <p><strong>Masterworks:</strong> ${e.works}</p>\n            <p>${e.description}</p>\n            <p class="quote-text"><em>"${e.quote}"</em></p>\n        </div>\n    `).join(""))}function renderSources(){const e=document.getElementById("sources-grid");e&&"undefined"!=typeof HISTORICAL_SOURCES&&(e.innerHTML=HISTORICAL_SOURCES.map(e=>`\n        <div class="source-card">\n            <h3>📖 ${e.title}</h3>\n            <span class="type-tag">${e.type}</span>\n            <p><strong>Evidence Value:</strong> ${e.reliability}</p>\n            <p>${e.summary}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");e&&"undefined"!=typeof TIMELINE_EVENTS&&(e.innerHTML=TIMELINE_EVENTS.map(e=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${e.year}</div>\n            <div class="timeline-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderScholars(),renderSources(),renderTimeline(),renderReferences(),initThemeToggle()});